LIB='''"""Reusable ARC grid helpers."""
from collections import deque


def background_components(g, line_color):
    """Connected 4-dir components of cells whose color != line_color."""
    H, W = len(g), len(g[0])
    seen = [[False] * W for _ in range(H)]
    comps = []
    for i in range(H):
        for j in range(W):
            if g[i][j] != line_color and not seen[i][j]:
                q = deque([(i, j)]); seen[i][j] = True; comp = []
                while q:
                    a, b = q.popleft(); comp.append((a, b))
                    for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        x, y = a + di, b + dj
                        if 0 <= x < H and 0 <= y < W and g[x][y] != line_color and not seen[x][y]:
                            seen[x][y] = True; q.append((x, y))
                comps.append(comp)
    return comps


def enclosed_cells(g, line_color):
    """Background (non-line_color) cells not reachable from the grid border."""
    H, W = len(g), len(g[0])
    free = [[g[i][j] != line_color for j in range(W)] for i in range(H)]
    seen = [[False] * W for _ in range(H)]
    q = deque((i, j) for i in range(H) for j in range(W)
              if (i in (0, H - 1) or j in (0, W - 1)) and free[i][j])
    for i, j in q:
        seen[i][j] = True
    while q:
        i, j = q.popleft()
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            a, b = i + di, j + dj
            if 0 <= a < H and 0 <= b < W and free[a][b] and not seen[a][b]:
                seen[a][b] = True; q.append((a, b))
    return {(i, j) for i in range(H) for j in range(W) if free[i][j] and not seen[i][j]}


def is_solid_rectangle(comp):
    """True if a cell set fills its bounding box exactly."""
    rs = [a for a, b in comp]; cs = [b for a, b in comp]
    return len(comp) == (max(rs) - min(rs) + 1) * (max(cs) - min(cs) + 1)


def line_color(g):
    """Least common color in the grid (the drawn-line color)."""
    return collections.Counter(c for row in g for c in row).most_common()[-1][0]


def fill_enclosed_rectangles(g, fill=4):
    """Fill each enclosed, solid-rectangle background region with `fill`."""
    lc = line_color(g)
